import * as THREE from 'three/webgpu';
import { texture } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Calculate plane dimensions from atlas region
  // Source rect: 0, 0, 512, 320 (width × height)
  const sourceWidth = 512;
  const sourceHeight = 320;
  const aspectRatio = sourceWidth / sourceHeight;

  // Create plane geometry scaled to atlas aspect ratio
  const planeHeight = 0.5;
  const planeWidth = planeHeight * aspectRatio;
  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  // Load texture via context (cached resource)
  const imageUrl = config.imageUrl || '/prism-mock/home/nodes/floating-accent.png';
  const textureMap = ctx.textureLoader.load(imageUrl);

  // Create material with TSL texture node for WebGPU compatibility
  const colorNode = texture(textureMap);
  const material = new THREE.MeshBasicMaterial({
    colorNode: colorNode,
    transparent: true,
    side: THREE.DoubleSide,
  });

  // Create and mount mesh
  const mesh = new THREE.Mesh(geometry, material);
  group.add(mesh);

  // Apply scene position, rotation, and scale from config
  const scenePos = config.scenePosition;
  if (scenePos) {
    group.position.set(scenePos.x ?? 0, scenePos.y ?? 0, scenePos.z ?? 0);
    if (scenePos.rotationXYZ) {
      const [rx, ry, rz] = scenePos.rotationXYZ;
      group.rotation.set(rx ?? 0, ry ?? 0, rz ?? 0);
    }
    if (scenePos.scaleXYZ) {
      const [sx, sy, sz] = scenePos.scaleXYZ;
      group.scale.set(sx ?? 1, sy ?? 1, sz ?? 1);
    }
  }

  // Cleanup handler: dispose geometry, material, and texture
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    textureMap.dispose();
  };

  // No event handlers for this static accent element
  group.userData.handlers = {};

  return group;
}
